package com.backoffice.eod.model

/** Pure position arithmetic. No Spark, no I/O: unit-testable.
  *
  * @param quantity signed share count; negative means short
  * @param avgCostCents weighted average cost per share in cents;
  *                     zero when quantity is zero
  */
final case class PositionState(quantity: Long, avgCostCents: Long) {
  def isFlat: Boolean = quantity == 0
}

object PositionMath {
  /** Applies one trade to a position state, returning the new
    * state and the realized P&L generated by the trade (zero
    * unless the trade closes some or all of an existing position).
    *
    * Rules:
    * - A buy against a short position closes the short first.
    * - A sell against a long position closes the long first.
    * - The closing portion realizes P&L at (trade price - avg cost).
    * - Any remainder opens or extends a position at the trade price.
    * - A position that goes flat resets average cost to zero.
    */
  def applyTrade(state: PositionState, side: String,
    qty: Long, priceCents: Long): (PositionState, Long) = {
    val signedQty = if (side == "BUY") qty else -qty
    if (state.isFlat) {
      (PositionState(signedQty, priceCents), 0L)
    } else if ((state.quantity > 0 && signedQty > 0) ||
      (state.quantity < 0 && signedQty < 0)) {
      // Extending: weighted average cost.
      val newQty = state.quantity + signedQty
      val newCost = (state.quantity * state.avgCostCents +
        signedQty * priceCents) / newQty
      (PositionState(newQty, newCost), 0L)
    } else {
      // Closing in whole or in part, possibly flipping.
      val closingQty = math.min(math.abs(state.quantity), math.abs(signedQty))
      val realized = closingQty * (priceCents - state.avgCostCents) *
        (if (state.quantity > 0) 1L else -1L)
      val remainder = state.quantity + signedQty
      if (remainder == 0) (PositionState(0, 0), realized)
      else (PositionState(remainder, priceCents), realized)
    }
  }

  /** Applies a split: quantity multiplies, average cost divides.
    * Uses integer division; any remainder cent is tracked by the
    * ledger job as a rounding adjustment (see Section 10.12). */
  def applySplit(state: PositionState, factor: Long): PositionState =
    if (state.isFlat) state
    else PositionState(state.quantity * factor, state.avgCostCents / factor)
}
